// Package topology decodes the document a system host's `graph` verb emits
// (topology.intropy.io/v1), as CI posts it to Atrium.
//
// Atrium shares no code with the CLI: the document is the contract. These
// types read only what the catalog needs; the raw document is stored as it
// came, so later views can read fields this package ignores.
package topology

import (
	"encoding/json"
	"errors"
	"fmt"
)

const (
	// APIVersion is the only schema Atrium understands. Anything else is
	// refused rather than guessed at, as the CLI does.
	APIVersion = "topology.intropy.io/v1"
	// Kind is the document kind under APIVersion.
	Kind = "SystemTopology"
)

// Document is one system's declared topology.
type Document struct {
	APIVersion    string         `json:"apiVersion"`
	Kind          string         `json:"kind,omitempty"`
	System        string         `json:"system"`
	Components    []Component    `json:"components,omitempty"`
	MessageGroups []MessageGroup `json:"messagegroups,omitempty"`
	Contracts     []Contract     `json:"contracts,omitempty"`
	Ports         []Port         `json:"ports,omitempty"`
	Services      []Service      `json:"services,omitempty"`
}

// Component is one block of the system, with its wiring inline.
type Component struct {
	Name       string     `json:"name"`
	Kind       string     `json:"kind"`
	Publishes  []TopicRef `json:"publishes,omitempty"`
	Subscribes []TopicRef `json:"subscribes,omitempty"`
	Ports      []PortUse  `json:"ports,omitempty"`
	// Uses lists the shared Dapr services (app IDs) the component invokes.
	Uses []string `json:"uses,omitempty"`
}

// TopicRef is a component's publication or subscription on a pub/sub topic.
type TopicRef struct {
	PubSub  string `json:"pubsub"`
	Topic   string `json:"topic"`
	Message string `json:"message,omitempty"`
	// Routes and Default are set on subscriptions only.
	Routes  []Route `json:"routes,omitempty"`
	Default string  `json:"default,omitempty"`
}

// Route is a content-based route of a subscription.
type Route struct {
	Message string `json:"message"`
	When    string `json:"when,omitempty"`
}

// PortUse is a component's use of an external port.
type PortUse struct {
	Port      string `json:"port"`
	Direction string `json:"direction"`
}

// MessageGroup is one entry of the messagegroups section. A group whose shape
// doesn't match contributes no messages instead of failing the document.
type MessageGroup struct {
	Name     string    `json:"name,omitempty"`
	Messages []Message `json:"messages,omitempty"`
}

// UnmarshalJSON tolerates groups of another shape, as the CLI does.
func (g *MessageGroup) UnmarshalJSON(b []byte) error {
	type plain MessageGroup
	var p plain
	if json.Unmarshal(b, &p) != nil {
		*g = MessageGroup{}
