// RevParse resolves any revision expression to a full sha.
func (g Client) RevParse(ctx context.Context, rev string) (string, error) {
	sha, err := g.run(ctx, "rev-parse", rev)
	if err != nil {
		return "", fmt.Errorf("resolve %s: %w", rev, err)
	}
	return sha, nil
}

// Clone clones url into dir. dir must not already exist.
func Clone(ctx context.Context, r command.Runner, url, dir string) error {
	return clone(ctx, r, url, dir, nil)
}

// IngestRequest is what CI posts after a merge to the main branch.
type IngestRequest struct {
	Repository string          `json:"repository"`
	Commit     string          `json:"commit"`
	Ref        string          `json:"ref"`
	Document   json.RawMessage `json:"document"`
	// Docs are Markdown files from the repository root, sent so they always
	// match the topology's commit.
	Docs []catalog.Doc `json:"docs,omitempty"`
}

// IngestResponse says what was stored.
type IngestResponse struct {
	System  string `json:"system"`
	Commit  string `json:"commit"`
	Created bool   `json:"created"`
}

func (s *Server) ingest(w http.ResponseWriter, r *http.Request) {
	if s.IngestToken == "" {
		writeError(w, http.StatusServiceUnavailable, "ingest is off: ATRIUM_INGEST_TOKEN is not set")
		return
	}
	token, ok := strings.CutPrefix(r.Header.Get("Authorization"), "Bearer ")
	if !ok || subtle.ConstantTimeCompare([]byte(token), []byte(s.IngestToken)) != 1 {
		writeError(w, http.StatusUnauthorized, "a valid bearer token is required")
		return
	}

	var req IngestRequest
	dec := json.NewDecoder(http.MaxBytesReader(w, r.Body, maxIngestBytes))
	if err := dec.Decode(&req); err != nil {
		var tooBig *http.MaxBytesError
		if errors.As(err, &tooBig) {
			writeError(w, http.StatusRequestEntityTooLarge, fmt.Sprintf("the request is over %d MB", maxIngestBytes>>20))
			return
		}
		writeError(w, http.StatusBadRequest, "the body is not valid JSON: "+err.Error())
		return
	}
	doc, err := validate(req)
	if err != nil {
		writeError(w, http.StatusBadRequest, err.Error())
		return
	}

	created, err := s.Store.SaveSnapshot(r.Context(), store.NewSnapshot{
		System:     doc.System,
		Repository: req.Repository,
		Commit:     req.Commit,
		Ref:        req.Ref,
		Document:   req.Document,
		Docs:       req.Docs,
	})
	if err != nil {
		s.Log.ErrorContext(r.Context(), "save snapshot", "system", doc.System, "commit", req.Commit, "err", err)
		writeError(w, http.StatusInternalServerError, "couldn't store the snapshot")
		return
	}
	s.Log.InfoContext(r.Context(), "topology received", "system", doc.System, "commit", req.Commit, "created", created)
	status := http.StatusOK
	if created {
		status = http.StatusCreated
	}
	writeJSON(w, status, IngestResponse{System: doc.System, Commit: req.Commit, Created: created})
}

func validate(req IngestRequest) (*topology.Document, error) {
	switch {
	case req.Repository == "":
		return nil, errors.New("repository is required, e.g. acme/order-flow")
	case req.Commit == "":
		return nil, errors.New("commit is required")
	case req.Ref == "":
		return nil, errors.New("ref is required, e.g. refs/heads/main")
	case len(req.Document) == 0:
		return nil, errors.New("document is required: the output of the system host's graph verb")
	case len(req.Docs) > maxDocs:
		return nil, fmt.Errorf("at most %d docs per snapshot", maxDocs)
	}
	for _, d := range req.Docs {
		if d.Path == "" {
			return nil, errors.New("every doc needs a path")
		}
	}
	return topology.Parse(req.Document)
}

func writeJSON(w http.ResponseWriter, status int, v any) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	json.NewEncoder(w).Encode(v) //nolint:errcheck
}

