func RunGraph(ctx context.Context, hostDir string) (*Topology, error) {
	// --development asks the host to include its development section (local
	// file resolutions for ports). The verb parses args by presence, so a
	// host built against an Intropy.Topology that predates the flag simply
	// ignores it and emits no section.
	t, _, err := runGraph(ctx, hostDir, "--development")
	return t, err
}

// RunGraphRecord executes the graph verb for a record to hand to someone else,
// and returns the bytes the host printed alongside the decoded record.
//
// Deliberately without --development: that section holds paths on this
// machine, which mean nothing to another reader and should not leave it.
func RunGraphRecord(ctx context.Context, hostDir string) (*Topology, []byte, error) {
	return runGraph(ctx, hostDir)
}

func runGraph(ctx context.Context, hostDir string, verbArgs ...string) (*Topology, []byte, error) {
	ctx, cancel := context.WithTimeout(ctx, GraphTimeout)
	defer cancel()

	build := exec.CommandContext(ctx, "dotnet", "build", hostDir, "-v", "q")
	var buildOut bytes.Buffer
	build.Stdout, build.Stderr = &buildOut, &buildOut
	if err := build.Run(); err != nil {
		return nil, nil, fmt.Errorf("build failed: %w%s", err, tail(buildOut.Bytes()))
	}

	args := append([]string{"run", "--no-build", "--no-launch-profile", "--project", hostDir, "--", "graph"}, verbArgs...)
	cmd := exec.CommandContext(ctx, "dotnet", args...)
	var stdout, stderr bytes.Buffer
	cmd.Stdout, cmd.Stderr = &stdout, &stderr
	if err := cmd.Run(); err != nil {
		return nil, nil, fmt.Errorf("graph verb failed: %w%s", err, tail(stderr.Bytes()))
	}
	raw := bytes.TrimSpace(stdout.Bytes())
	t, err := Decode(bytes.NewReader(raw))
	if err != nil {
		// The stdout tail, not stderr: a decode failure means the verb printed
		// something other than the record, and that something is the evidence.
		return nil, nil, fmt.Errorf("%w%s", err, tail(raw))
	}
	return t, raw, nil
}

